{"code":"q4","title":"您的肌肉量是否处于正常区间？（预检报告的人体成分分析上为准）","type":"single","role":"assessment","section":"体感与代谢","options":[{"code":"a","label":"低于正常水平 - 预检报告上绿色向下箭头"},{"code":"b","label":"正常水平 - 预检报告上黑色字体"},{"code":"c","label":"高于正常水平 - 预检报告上红色向上箭头"},{"code":"d","label":"不知道，没测过"}],"required":true,"hint":"可由最近一次体脂秤测量自动带入，也可自行修改","unit":"","prefill":"muscle_mass","screenGroup":null,"multiline":false,"confidence":"confident"},
