"S":{"code":"S","name":"S 型","color":"#EFCB3A","system":"神经主导","traits":["消化极弱","不吃生食"],"strategy":["五餐均分，少食多餐","食物一律煮熟煮烂，不吃生食","晚餐少油少盐"],"meals":[{"label":"早餐","percent":20,"note":"以易消化、富含碳水的流食／软食为主（如小米粥、奶昔、软面条、鸡蛋羹等）"},{"label":"上午加餐","percent":20,"note":""},{"label":"午餐","percent":20,"note":"最好是煮熟煮烂的中等份量熟食，包含蛋白质（如瘦肉、禽类、豆制品、水产品）、碳水（杂粮饭、面条、粥、薯类）和各种蔬菜"},{"label":"下午加餐","percent":20,"note":""},{"label":"晚餐","percent":20,"note":"煮熟的蛋白质（如瘦肉、禽类、豆制品、水产品）、碳水（软烂杂粮饭、面条、粥、薯类）和绿叶蔬菜（最好包括十字花科、大蒜或韭葱），少油少盐"}],"confidence":"needs_review"},
"D":{"code":"D","name":"D 型","color":"#9C63C6","system":"消化+神经主导","traits":["胰岛素抵抗风险高","需拉长餐间隔"],"strategy":["严格禁止加餐","午餐占比极大","有运动日按 3（早餐）:5（午餐）:2（晚餐）"],"meals":[{"label":"早餐","percent":20,"note":"选择易消化的简单流质（如一杯咖啡、健康奶昔等）"},{"label":"午餐","percent":60,"note":"一天中最丰盛的一餐，需多吃蔬菜，并富含碳水化合物（如杂粮饭、薯类）、蛋白质和健康的脂肪酸"},{"label":"晚餐","percent":20,"note":"丰富的蔬菜搭配肉类（蔬菜与肉类比例 1:1），无碳水或仅有极少量碳水（取决于当天的活动水平）"}],"confidence":"needs_review"},
"G":{"code":"G","name":"G 型","color":"#7A93C2","system":"消化主导","traits":["代谢极慢","需严格限热量与动物蛋白"],"strategy":["严格禁止加餐","采用倒金字塔分配，晚餐极少","有运动日按 6（早餐）:3（午餐）:1（晚餐）"],"meals":[{"label":"早餐","percent":50,"note":"加大蔬菜量，搭配适量蛋白质（优先选择植物蛋白，如豆制品）、低 GI 碳水化合物，要求低动物脂肪"},{"label":"午餐","percent":40,"note":"加大蔬菜量（少吃淀粉类蔬菜），搭配低蛋白或无蛋白（优先植物蛋白，如豆制品）"},{"label":"晚餐","percent":10,"note":"低热量收尾，大量吃蔬菜，完全不吃蛋白质（如瘦肉、禽类、豆制品、水产品）和碳水化合物（杂粮饭、面条、粥、薯类），可少量喝些肉汤"}],"confidence":"needs_review"},
